contract InvMutTest {
    C c;
    bool origReverted;
    bool mutReverted;

    constructor(C _c) {
        c = _c;
    }

    function test(address from, address caddress, address[] memory _tos, uint v) public {
        require(_tos.length > 0);
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        // Simulate original: call all _tos, revert if any fails
        (bool origOk, ) = address(this).call(abi.encodeWithSelector(this.simOrig.selector, from, caddress, _tos, v, id));
        origReverted = !origOk;
        // Simulate mutant: call all but last _tos
        (bool mutOk, ) = address(this).call(abi.encodeWithSelector(this.simMut.selector, from, caddress, _tos, v, id));
        mutReverted = !mutOk;
        // The distinguishing property: if original does not revert, mutant must not revert.
        // M violates this because for some _tos where the last element would cause a revert,
        // original reverts (so impl holds vacuously when orig reverts) but mutant succeeds.
        assert(!(!origReverted && mutReverted));
    }

    function simOrig(address from, address caddress, address[] memory _tos, uint v, bytes4 id) external {
        for(uint i=0;i<_tos.length;i++){
            (bool _s,) = caddress.call(abi.encodeWithSelector(id,from,_tos[i],v));
            require(_s);
        }
    }

    function simMut(address from, address caddress, address[] memory _tos, uint v, bytes4 id) external {
        for(uint i=0;i<_tos.length-1;i++){
            (bool _s,) = caddress.call(abi.encodeWithSelector(id,from,_tos[i],v));
            require(_s);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint v) public {
        require(_tos.length > 0);
        bool originalReverted;
        try c.transfer(from, caddress, _tos, v) {
            originalReverted = false;
        } catch {
            originalReverted = true;
        }
        bool lastCallReverted;
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        (bool success,) = caddress.call(abi.encodeWithSelector(id, from, _tos[_tos.length - 1], v));
        lastCallReverted = !success;
        assert(!originalReverted || lastCallReverted);
    }
    receive() external payable {}
}

