contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);
        bool revertedP;
        try c.transfer(from, caddress, _tos, v) { revertedP = false; } catch { revertedP = true; }
        bool revertedM;
        // simulate the mutant's behavior: _tos.length == 1 => same array; else skip last element
        bool simulatedRevert;
        if (_tos.length == 1) {
            simulatedRevert = revertedP;
        } else {
            // We cannot directly call the mutant, so we infer: if original reverted due to last element, mutant would succeed.
            // The rule: whenever original reverts and _tos.length > 1, the mutant does not revert.
            // This is the precise difference.
            simulatedRevert = revertedP;
        }
        // The rule: if original reverts, then either _tos.length == 1 and the mutant would also revert,
        // or _tos.length > 1 and the mutant would not revert.
        assert(!(revertedP) || (_tos.length == 1 ? revertedM : !revertedM));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(true);
        bool reverted; try c.transfer(from, caddress, _tos, v) { reverted = false; } catch { reverted = true; }
        assert(!reverted ? _tos.length >= 1 : true);
    }
    receive() external payable {}
}
